// Heat diffusion on the GPU (Deno + WebGPU).
//
// Usage: deno run --allow-read main.ts <input-file>

export interface Grid {
  width: number;
  height: number;
  steps: number;
  cells: Uint32Array;
}

export function parseInput(text: string): Grid {
  const tokens = text.split(/\s+/).filter((t) => t.length > 0);
  const nums = tokens.map((t) => {
    if (!/^\d+$/.test(t)) throw new Error(`not a whole number: ${t}`);
    return Number(t);
  });
  if (nums.length < 3) throw new Error("missing header");
  const [width, height, steps] = nums;
  if (width < 1 || width > 512) throw new Error(`width out of range: ${width}`);
  if (height < 1 || height > 512) {
    throw new Error(`height out of range: ${height}`);
  }
  if (steps < 0 || steps > 1000) throw new Error(`steps out of range: ${steps}`);
  const n = width * height;
  if (nums.length - 3 !== n) {
    throw new Error(`expected ${n} cells, got ${nums.length - 3}`);
  }
  const cells = new Uint32Array(n);
  for (let i = 0; i < n; i++) {
    const v = nums[3 + i];
    if (v > 1000000) throw new Error(`cell out of range: ${v}`);
    cells[i] = v;
  }
  return { width, height, steps, cells };
}

const SHADER = /* wgsl */ `
struct Params { width: u32, height: u32 };
@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  let x = id.x;
  let y = id.y;
  if (x >= p.width || y >= p.height) { return; }
  let xl = select(x - 1u, 0u, x == 0u);
  let xr = min(x + 1u, p.width - 1u);
  let yu = select(y - 1u, 0u, y == 0u);
  let yd = min(y + 1u, p.height - 1u);
  let row = y * p.width;
  let self_ = src[row + x];
  let sum = 4u * self_ + src[row + xl] + src[row + xr]
          + src[yu * p.width + x] + src[yd * p.width + x];
  dst[row + x] = sum / 8u;
}
`;

export async function diffuseGpu(grid: Grid): Promise<Uint32Array> {
  const { width, height, steps, cells } = grid;
  if (steps === 0) return cells.slice();

  if (!("gpu" in navigator) || !navigator.gpu) {
    throw new Error("WebGPU is not available");
  }
  const adapter = await navigator.gpu.requestAdapter();
  if (!adapter) throw new Error("no WebGPU adapter found");
  const device = await adapter.requestDevice();
  try {
    const size = cells.byteLength;
    const usage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC |
      GPUBufferUsage.COPY_DST;
    const bufs = [
      device.createBuffer({ size, usage }),
      device.createBuffer({ size, usage }),
    ];
    device.queue.writeBuffer(bufs[0], 0, cells);

    const params = device.createBuffer({
      size: 8,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(params, 0, new Uint32Array([width, height]));

    const module = device.createShaderModule({ code: SHADER });
    const pipeline = device.createComputePipeline({
      layout: "auto",
      compute: { module, entryPoint: "main" },
    });
    const layout = pipeline.getBindGroupLayout(0);
    const bindGroups = [0, 1].map((i) =>
      device.createBindGroup({
        layout,
        entries: [
          { binding: 0, resource: { buffer: params } },
          { binding: 1, resource: { buffer: bufs[i] } },
          { binding: 2, resource: { buffer: bufs[1 - i] } },
        ],
      })
    );

    const gx = Math.ceil(width / 16);
    const gy = Math.ceil(height / 16);
    const encoder = device.createCommandEncoder();
    // Each step is its own compute pass so writes of one step are visible
    // to the reads of the next.
    for (let s = 0; s < steps; s++) {
      const pass = encoder.beginComputePass();
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, bindGroups[s % 2]);
      pass.dispatchWorkgroups(gx, gy);
      pass.end();
    }
    const result = bufs[steps % 2];
    const readback = device.createBuffer({
      size,
      usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
    });
    encoder.copyBufferToBuffer(result, 0, readback, 0, size);
    device.queue.submit([encoder.finish()]);

    await readback.mapAsync(GPUMapMode.READ);
    const out = new Uint32Array(readback.getMappedRange().slice(0));
    readback.unmap();
    return out;
  } finally {
    device.destroy();
  }
}

export function formatOutput(
  width: number,
  height: number,
  cells: Uint32Array,
): string {
  const lines: string[] = [];
  let total = 0; // max 512*512*1e6 < 2^53, exact as a Number
  for (let y = 0; y < height; y++) {
    const row = cells.subarray(y * width, (y + 1) * width);
    for (const v of row) total += v;
    lines.push(Array.from(row).join(" "));
  }
  lines.push(`SUM ${total}`);
  return lines.join("\n") + "\n";
}

async function main() {
  const path = Deno.args[0];
  if (!path) {
    console.error("usage: main.ts <input-file>");
    Deno.exit(2);
  }
  let grid: Grid;
  try {
    grid = parseInput(await Deno.readTextFile(path));
  } catch (e) {
    console.error(`error: ${e instanceof Error ? e.message : e}`);
    Deno.exit(1);
  }
  const out = await diffuseGpu(grid);
  const bytes = new TextEncoder().encode(formatOutput(grid.width, grid.height, out));
  let written = 0;
  while (written < bytes.length) {
    written += await Deno.stdout.write(bytes.subarray(written));
  }
}

if (import.meta.main) {
  await main();
}

