import { diffuseGpu, formatOutput, Grid, parseInput } from "./main.ts";

function assertEquals<T>(a: T, b: T, msg = "") {
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    throw new Error(`${msg} expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
  }
}

// CPU reference used only to check the GPU kernel.
function reference(g: Grid): Uint32Array {
  const { width: w, height: h } = g;
  let cur = g.cells.slice();
  for (let s = 0; s < g.steps; s++) {
    const next = new Uint32Array(w * h);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const at = (xx: number, yy: number) =>
          cur[Math.min(Math.max(yy, 0), h - 1) * w + Math.min(Math.max(xx, 0), w - 1)];
        next[y * w + x] = Math.floor(
          (4 * at(x, y) + at(x - 1, y) + at(x + 1, y) + at(x, y - 1) + at(x, y + 1)) / 8,
        );
      }
    }
    cur = next;
  }
  return cur;
}

function rand(n: number) {
  return Math.floor(Math.random() * n);
}

Deno.test("parse and format", () => {
  const g = parseInput("2 2 0\n1 2\n3 4\n");
  assertEquals(formatOutput(g.width, g.height, g.cells), "1 2\n3 4\nSUM 10\n");
});

Deno.test("single cell is a fixed point", async () => {
  const g = parseInput("1 1 5\n1000000\n");
  assertEquals(Array.from(await diffuseGpu(g)), [1000000]);
});

Deno.test("small hand-checked case", async () => {
  // 3x1, one step: [0,8,0] -> left: (0+0+8+0+0)/8=1, mid: (32+0+0+8+8)/8=6, right: 1
  const g = parseInput("3 1 1\n0 8 0\n");
  assertEquals(Array.from(await diffuseGpu(g)), [1, 6, 1]);
});

Deno.test("random grids match reference", async () => {
  const shapes = [[1, 7], [7, 1], [16, 16], [17, 33], [100, 3], [512, 512]];
  for (const [w, h] of shapes) {
    const steps = w * h > 10000 ? 20 : rand(60) + 1;
    const cells = new Uint32Array(w * h).map(() => rand(1000001));
    const g = { width: w, height: h, steps, cells };
    assertEquals(Array.from(await diffuseGpu(g)), Array.from(reference(g)), `${w}x${h}x${steps}`);
  }
});

Deno.test("max steps on max values", async () => {
  const g = { width: 5, height: 4, steps: 1000, cells: new Uint32Array(20).fill(1000000) };
  assertEquals(Array.from(await diffuseGpu(g)), Array.from(g.cells));
  const g2 = { width: 9, height: 6, steps: 1000, cells: new Uint32Array(54).map(() => rand(1000001)) };
  assertEquals(Array.from(await diffuseGpu(g2)), Array.from(reference(g2)));
});
